const discriminant = () => { const a = pick([1, 2, 3, -1]), b = R(-6, 6), c = pick([-4, -3, -2, -1, 1, 2, 3, 4]);
  return cor(`${K('\\Delta = b^2 - 4ac = ' + nb(b) + '^2 - 4 \\times ' + nb(a) + ' \\times ' + nb(c) + ' = ' + b * b + pl(-4 * a * c) + ' = ' + (b * b - 4 * a * c))}.`) && question(`Calculez le discriminant de ${K(tri(a, b, c))}.`, b * b - 4 * a * c, [b * b + 4 * a * c, b * b - a * c, b - 4 * a * c, -b * b - 4 * a * c, b * b - 4 * a * c + 4]); };
