const VALEURS = ['0', '1', '-1', '\\dfrac12', '-\\dfrac12', '\\dfrac{\\sqrt2}{2}', '-\\dfrac{\\sqrt2}{2}', '\\dfrac{\\sqrt3}{2}', '-\\dfrac{\\sqrt3}{2}'];
