  if (type === 3) { const b = pick([2, 3]), e = pick([2, 3]); return cor(`${K(e + '\\ln ' + b + ' = \\ln\\left(' + b + '^{' + e + '}\\right)')}, donc ${K('e^{' + e + '\\ln ' + b + '} = ' + b + '^{' + e + '} = ' + b ** e)}.`) && question(`Simplifiez ${K('e^{' + e + '\\ln ' + b + '}')}.`, b ** e, [e * b, b + e, 'e^{' + e * b + '}', e ** b + 1]); }
